head.script:
scwin.gVar = {
    "cStyle" : "",
    "cStyleParent" : "",
}


scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof parent1 !== 'undefined') {
        parent1.remove();
    }

    // 조건 설정   
    let cStyle = scwin.gVar["cStyle"];
    cStyle += "width:148px;height:100px;background-color:var(--ws-gray-300);" 
    let cStyleParent = scwin.gVar["cStyleParent"];


    let properties = {
        style: cStyle,
    };

    let cList = $c.gcm.createCList(properties);   

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();

    let strParent = '';
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strParent += '<xf:group ' + strNameSpace + ' style="background-color:var(--ws-green-100); height: 400px; '+cStyleParent+'">';
    strParent += '</xf:group>';

    scwin.parent1 = await $p.dynamicCreate(
        "parent1",
        "group",
        strParent,
        grp_comp    
    );

    strTarget += '<w2:tabControl ' + strNameSpace + ' ' + cList + ' id="" alwaysDraw="false">';
    strTarget += '<w2:tabs disabled="false" style="height:40px;" id="tabs1" label="Tabs1"></w2:tabs>';
    strTarget += '<w2:tabs disabled="false" style="height:40px" id="tabs2" label="Tabs2"></w2:tabs>';
    strTarget += '<w2:content alwaysDraw="false" style="height:160px;" id="content1">';
    strTarget += '<w2:button style="width:80px; height:23px; " id="" label="tabs1"></w2:button>';
    strTarget += '</w2:content>';
    strTarget += '<w2:content alwaysDraw="false" style="height:160px" id="content2">';
    strTarget += '<xf:input id="" style="width:144px; height:21px; " initValue="tabs2"></xf:input>';
    strTarget += '</w2:content>';
    strTarget += '</w2:tabControl>';

    // target 생성
    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "tabControl",
        strTarget,
        parent1
    );
}
